import React from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';

const AdminPage: React.FC = () => {
  const navigate = useNavigate();

  const handleUploadClick = () => {
    navigate('/upload');
  };

  const handleViewClick = () => {
    navigate('/question');
  };

  const handleDeleteClick = async () => {
    try {
      const response = await fetch("http://localhost:5000/delete", {
        method: "DELETE",
        headers: {
          "Content-Type": "application/json",
        },
      });

      if (response.ok) {
        alert("Deleted successfully!");
      } else {
        alert("Failed to delete.");
      }
    } catch (err: any) {
      alert("Error: " + err.message);
    }
  };

  const handleDownloadClick = async () => {
    try {
      const response = await fetch('http://localhost:5000/download_csv');
      if (!response.ok) {
        throw new Error('Failed to download CSV');
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'history_data.csv';
      document.body.appendChild(a);
      a.click();
      a.remove();
    } catch (error) {
      console.error('Error downloading CSV:', error);
    }
  };

  return (
    <div className="admin-container">
      <div className="admin-content">
        <motion.div 
          className="admin-image"
          initial={{ opacity: 0, x: -50 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.8 }}
        >
          <img src="/admin-image.png" alt="Admin" className="image" />
        </motion.div>

        <motion.div 
          className="admin-actions"
          initial={{ opacity: 0, x: 50 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.8 }}
        >
          <button onClick={handleUploadClick} className="action-button">Upload</button>
          <button onClick={handleDeleteClick} className="action-button">Delete</button>
          <button onClick={handleDownloadClick} className="action-button">Download CSV</button>
          <button onClick={handleViewClick} className="action-button">View Dataset</button>
        </motion.div>
      </div>
    </div>
  );
};

export default AdminPage;

// Styles
const styles = `
  .admin-container {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;
    background-color: #f4f4f4;
  }
  .admin-content {
    display: flex;
    align-items: center;
    gap: 40px;
    background: white;
    padding: 40px;
    border-radius: 12px;
    box-shadow: 0 10px 20px rgba(0, 0, 0, 0.1);
  }
  .admin-image .image {
    width: 250px;
    height: auto;
    border-radius: 10px;
  }
  .admin-actions {
    display: flex;
    flex-direction: column;
    gap: 15px;
  }
  .action-button {
    padding: 12px 24px;
    font-size: 16px;
    font-weight: bold;
    background-color: #4CAF50;
    color: white;
    border: none;
    cursor: pointer;
    border-radius: 8px;
    transition: transform 0.2s, background-color 0.3s;
  }
  .action-button:hover {
    background-color: #45a049;
    transform: scale(1.05);
  }
`;

const styleTag = document.createElement("style");
styleTag.innerHTML = styles;
document.head.appendChild(styleTag);
